css:
/* ========== CONFIGURACIÓN GLOBAL ========== */
* {
    font-family: Arial, sans-serif;
    font-size: 12px;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body.print-format {
    background: white;
    color: #000;
}

/* ========== CONTENEDOR PRINCIPAL ========== */
.print-format-container {
    margin: 10px;
    max-width: 100%;
}

/* ========== HEADER ========== */
#information-table {
    width: 100%;
    border: none;
    margin-bottom: 10px;
}

#information-table td {
    vertical-align: middle;
    border: none !important;
    padding: 5px !important;
}

/* Logo */
.logo {
    display: flex;
    justify-content: center;
    align-items: center;
}

.logo img {
    max-height: 90px;
    width: auto;
    height: auto;
    max-width: 100%;
    display: block;
}

/* ========== TIPOGRAFÍA ========== */
h3 {
    font-size: 16px;
    font-weight: bold;
    margin: 4px 0;
    color: #000;
}

h4 {
    font-size: 14px;
    font-weight: bold;
    margin: 8px 0 4px 0;
    color: #000;
}

h5 {
    font-size: 13px;
    font-weight: bold;
    margin: 6px 0 4px 0;
    color: #000;
}

p {
    margin: 4px 0;
    line-height: 1.4;
    text-align: justify;
}

/* ========== TABLAS ========== */
table {
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
}

th, td {
    border: 1px solid #000;
    padding: 4px 6px;
    font-size: 11px;
    line-height: 1.3;
    vertical-align: top;
}

th {
    font-weight: bold;
    background-color: #f5f5f5;
}

/* Tabla principal sin bordes internos */
table.main-table,
table.main-table td,
table.main-table th {
    border: none !important;
}

/* Tabla de información del paciente */
#table-info td {
    border: none !important;
    padding: 3px 6px !important;
    line-height: 1.4;
}

#table-info b {
    font-weight: bold;
    display: inline-block;
    min-width: fit-content;
}

/* Tabla compacta */
.table-compact td {
    padding: 2px 4px !important;
}

/* Información complementaria */
.info-complement td {
    border: none !important;
    line-height: 1.4;
}

/* ========== SECCIONES ========== */
.datos-generales {
    margin-top: 10px;
    margin-bottom: 10px;
    border-top: 2px solid #000;
    border-bottom: 2px solid #000;
    padding: 11px 0;
}

.datos-medicamentos {
    margin-top: 10px;
    padding: 8px 0;
}

.prescripciones {
    margin-top: 10px;
    
}
.examenes{
    border: 1px solid black;
    padding: 2px;
}
/* ========== FIRMA ========== */
.footer {
    margin-top: 60px;
    text-align: left;
    page-break-inside: avoid;
}

.sign-section {
    display: inline-block;
    min-width: 300px;
}

.signature {
    text-align: left;
    line-height: 1.6;
}

.signature br {
    line-height: 1.4;
}

/* ========== CONTROL DE SALTOS DE PÁGINA ========== */
table.main-table,
.datos-generales,
.footer {
    page-break-inside: avoid;
}

tr {
    page-break-inside: avoid;
}

tbody {
    page-break-inside: auto;
}

h3, h4, h5 {
    page-break-after: avoid;
}

/* ========== MEDIA QUERIES PARA IMPRESIÓN ========== */
@media print {
    body.print-format {
        margin: 0;
        padding: 0;
    }
    
    .print-format-container {
        margin: 8mm;
    }
    
    * {
        font-size: 11px;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
    
    .logo img {
        max-height: 75px;
    }
    
    h3 {
        font-size: 15px;
    }
    
    h4 {
        font-size: 13px;
    }
    
    h5 {
        font-size: 12px;
    }
    
    th, td {
        font-size: 10px !important;
        padding: 2px 4px !important;
    }
    
    #table-info td {
        padding: 2px 4px !important;
    }
    
    .footer {
        margin-top: 50px;
    }
    
    /* Evitar huérfanas y viudas */
    p, td, th {
        orphans: 3;
        widows: 3;
    }
}

/* ========== MEDIA QUERY PARA LANDSCAPE ========== */
@media print and (orientation: landscape) {
    .logo img {
        max-height: 100px;
    }
    
    .print-format-container {
        margin: 10mm 15mm;
    }
}
